use vstd::prelude::*;
use vstd::vec::Vec;

fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let k = if m > n { m } else { n };

    // If `a` has length 1, replicate its sole element k times;
    // otherwise, it already has length k (because m == n) so we can reuse it.
    let out_a: Vec<i8> = if m == 1 {
        vec![a[0]; k]
    } else {
        a
    };

    // Similarly for `b`.
    let out_b: Vec<i8> = if n == 1 {
        vec![b[0]; k]
    } else {
        b
    };

    (out_a, out_b)
}